public String minWindow(String A, String B) {
    if (A.length() < B.length()) {
        return "-1";
    }

    HashMap<Character, Integer> target = new HashMap<>();
    for (char c : B.toCharArray()) {
        target.put(c, target.getOrDefault(c, 0) + 1);
    }

    HashMap<Character, Integer> currentWindow = new HashMap<>();
    int required = target.size();
    int formed = 0;
    int left = 0;
    int right = 0;

    int minLength = Integer.MAX_VALUE;
    int start = 0;

    while (right < A.length()) {
        char c = A.charAt(right);
        currentWindow.put(c, currentWindow.getOrDefault(c, 0) + 1);

        // .intValue() on both sides: Integer == Integer breaks past the 127 cache
        if (target.containsKey(c) &&
                currentWindow.get(c).intValue() == target.get(c).intValue()) {
            formed++;
        }

        while (formed == required) {
            if (right - left + 1 < minLength) {
                minLength = right - left + 1;
                start = left;
            }

            char leftChar = A.charAt(left);
            currentWindow.put(leftChar, currentWindow.get(leftChar) - 1);

            if (target.containsKey(leftChar) &&
                    currentWindow.get(leftChar).intValue() < target.get(leftChar).intValue()) {
                formed--;
            }

            left++;
        }

        right++;
    }

    return minLength == Integer.MAX_VALUE ? "-1" : A.substring(start, start + minLength);
}

public String findAthPerfectNumber(int A) {
    int len = 1;
    long count = 2;    // number of halves of this length
    long consumed = 0; // perfect numbers with a shorter half

    while (consumed + count < A) {
        consumed += count;
        count *= 2;
        len++;
    }

    long index = A - consumed - 1; // 0-based rank within this half-length block
    StringBuilder half = new StringBuilder();
    for (int bit = len - 1; bit >= 0; bit--) {
        if (((index >> bit) & 1) == 0) {
            half.append('1');
        } else {
            half.append('2');
        }
    }

    String first = half.toString();
    String second = new StringBuilder(first).reverse().toString();
    return first + second;
}

public int bestTimeToBuyAndSellStocksII(int[] A) {
    if (A == null || A.length < 2) {
        return 0;
    }
    long profit = 0;
    for (int i = 1; i < A.length; i++) {
        if (A[i] > A[i - 1]) {
            profit += A[i] - A[i - 1];
        }
    }
    return (int) profit;
}
